package com.example.starter.reinsurance.repository;

import com.example.starter.reinsurance.domain.Treaty;
import java.sql.Timestamp;
import java.time.Clock;
import java.util.List;
import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * 再保合约仓储。
 */
@Repository
public class TreatyRepository {

    private static final RowMapper<Treaty> MAPPER = (rs, n) -> {
        Treaty treaty = new Treaty();
        treaty.setId(rs.getLong("id"));
        treaty.setContractNo(rs.getString("contract_no"));
        treaty.setCessionRate(rs.getBigDecimal("cession_rate"));
        treaty.setPerPolicyLimit(rs.getBigDecimal("per_policy_limit"));
        if (rs.wasNull()) {
            treaty.setPerPolicyLimit(null);
        }
        Timestamp createdAt = rs.getTimestamp("created_at");
        if (createdAt != null) {
            treaty.setCreatedAt(createdAt.toInstant());
        }
        return treaty;
    };

    private final JdbcTemplate jdbcTemplate;
    private final Clock clock;

    public TreatyRepository(JdbcTemplate jdbcTemplate, Clock clock) {
        this.jdbcTemplate = jdbcTemplate;
        this.clock = clock;
    }

    public Treaty insert(Treaty treaty) {
        java.time.Instant now = java.time.Instant.now(clock);
        treaty.setCreatedAt(now);
        jdbcTemplate.update(
                "INSERT INTO treaty (contract_no, cession_rate, per_policy_limit, created_at) VALUES (?,?,?,?)",
                treaty.getContractNo(),
                treaty.getCessionRate(),
                treaty.getPerPolicyLimit(),
                Timestamp.from(now));
        treaty.setId(jdbcTemplate.queryForObject("SELECT IDENTITY()", Long.class));
        return treaty;
    }

    public Optional<Treaty> findByContractNo(String contractNo) {
        List<Treaty> list =
                jdbcTemplate.query("SELECT * FROM treaty WHERE contract_no = ?", MAPPER, contractNo);
        return list.stream().findFirst();
    }

    public Treaty getByContractNo(String contractNo) {
        return findByContractNo(contractNo)
                .orElseThrow(() -> new com.example.starter.reinsurance.common.ApiException(
                        com.example.starter.reinsurance.common.ErrorCode.NOT_FOUND,
                        "合约不存在: " + contractNo));
    }
}

package com.example.starter.reinsurance.repository;

import com.example.starter.reinsurance.domain.Policy;
import java.sql.Date;
import java.sql.Timestamp;
import java.time.Clock;
import java.util.List;
import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * 分出保单仓储。
 */
@Repository
public class PolicyRepository {

    private static final RowMapper<Policy> MAPPER = (rs, n) -> {
        Policy policy = new Policy();
        policy.setId(rs.getLong("id"));
        policy.setPolicyNo(rs.getString("policy_no"));
        policy.setContractId(rs.getLong("contract_id"));
        policy.setPremium(rs.getBigDecimal("premium"));
        Date effective = rs.getDate("effective_date");
        if (effective != null) {
            policy.setEffectiveDate(effective.toLocalDate());
        }
        long billId = rs.getLong("bill_id");
        policy.setBillId(rs.wasNull() ? null : billId);
        Timestamp createdAt = rs.getTimestamp("created_at");
        if (createdAt != null) {
            policy.setCreatedAt(createdAt.toInstant());
        }
        return policy;
    };

    private final JdbcTemplate jdbcTemplate;
    private final Clock clock;

    public PolicyRepository(JdbcTemplate jdbcTemplate, Clock clock) {
        this.jdbcTemplate = jdbcTemplate;
        this.clock = clock;
    }

    public Policy insert(Policy policy) {
        java.time.Instant now = java.time.Instant.now(clock);
        policy.setCreatedAt(now);
        jdbcTemplate.update(
                "INSERT INTO policy (policy_no, contract_id, premium, effective_date, bill_id, created_at) "
                        + "VALUES (?,?,?,?,?,?)",
                policy.getPolicyNo(),
                policy.getContractId(),
                policy.getPremium(),
                Date.valueOf(policy.getEffectiveDate()),
                policy.getBillId(),
                Timestamp.from(now));
        policy.setId(jdbcTemplate.queryForObject("SELECT IDENTITY()", Long.class));
        return policy;
    }

    public Optional<Policy> findByPolicyNo(String policyNo) {
        List<Policy> list =
                jdbcTemplate.query("SELECT * FROM policy WHERE policy_no = ?", MAPPER, policyNo);
        return list.stream().findFirst();
    }

    public Policy getByPolicyNo(String policyNo) {
        return findByPolicyNo(policyNo)
                .orElseThrow(() -> new com.example.starter.reinsurance.common.ApiException(
                        com.example.starter.reinsurance.common.ErrorCode.NOT_FOUND,
                        "保单不存在: " + policyNo));
    }

    /**
     * 仅当保单尚未出账时将其挂到账单上（条件更新，防重复出账）。
     *
     * @return 受影响行数；0 表示保单已出账
     */
    public int attachToBillIfFree(Long policyId, Long billId) {
        return jdbcTemplate.update(
                "UPDATE policy SET bill_id = ? WHERE id = ? AND bill_id IS NULL",
                billId,
                policyId);
    }
}

