public class IdempotencyService {

    /** 首次业务动作的结果。 */
    public record Outcome<T>(int httpStatus, String resultRef, T body) {
        public static <T> Outcome<T> ok(String resultRef, T body) {
            return new Outcome<>(200, resultRef, body);
        }
    }

