        String fingerprint = fingerprint(operation, requestId, payload);
        // 同键并发时最多经历“等待占位 → 占位被失败请求清理 → 自行抢占”两轮。
        for (int attempt = 0; attempt < 2; attempt++) {
            IdempotencyRecord existing = repository.find(requestId);
            if (existing != null) {
