                ErrorCode.CONCURRENT_MODIFICATION,
                "同 requestId 的并发请求冲突，请稍后重试: " + requestId);
    }

    private IdempotentResult runFirstRequest(String requestId, Supplier<Outcome<Object>> action) {
        Outcome<Object> outcome;
        try {
