            IdempotencyRecord completed = waitForCompletion(record.getRequestId());
            return toResult(completed, true);
        }
        return toResult(record, true);
    }

    private IdempotentResult toResult(IdempotencyRecord record, boolean replay) {
        try {
            JsonNode node = objectMapper.readTree(record.getResultJson());
            return new IdempotentResult(node, record.getHttpStatus(), record.getResultRef(), replay);
        } catch (Exception e) {
            throw new IllegalStateException("无法解析首次结果: requestId=" + record.getRequestId(), e);
        }
    }

    private IdempotencyRecord waitForCompletion(String requestId) {
        long deadline = System.currentTimeMillis() + PLACEHOLDER_WAIT_MILLIS;
        IdempotencyRecord record;
        do {
            record = repository.find(requestId);
            if (record != null && record.getHttpStatus() != null && record.getHttpStatus() > 0) {
                return record;
            }
            if (record == null) {
                // 占位请求业务失败并清理了占位；并发请求可自行尝试执行。
                if (repository.tryInsertPlaceholder(
