        throw new ApiException(
                ErrorCode.CONCURRENT_MODIFICATION,
                "同 requestId 的并发请求尚未完成: " + requestId);
    }

    private String fingerprintOf(String requestId) {
        return fingerprint("UNKNOWN", requestId, null);
    }

    @Transactional
    public void safeDelete(String requestId) {
        repository.delete(requestId);
    }

    /**
     * 计算指纹：operation、requestId 与全部业务字段的规范化 JSON 均参与哈希。
     */
    public String fingerprint(String operation, String requestId, Object payload) {
        try {
            String canonical = canonicalMapper.writeValueAsString(payload == null ? new Object() : payload);
            String raw = operation + "|" + requestId + "|" + canonical;
