        this.repository = repository;
        this.objectMapper = objectMapper;
        // Map 键排序，保证同一业务字段集合无论构造顺序如何指纹都一致。
        this.canonicalMapper =
                objectMapper.copy().configure(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS, true);
    }

