            throw new ApiException(ErrorCode.ILLEGAL_STATE, "保单号已存在: " + request.policyNo());
        }
        return new PolicyResponse(
                policy.getPolicyNo(),
                treaty.getContractNo(),
                policy.getPremium(),
                policy.getEffectiveDate(),
                null);
    }
}

